import com.hoonjay.filmroom.core.*;
import java.io.*;import java.nio.*;import java.nio.file.*;import java.util.*;
/** Press-specific contracts: exact ratio, rotation, bounded detail and untouched RAW samples. */
public final class PressImageTests {
  static int checks;static void ok(boolean v,String name){checks++;if(!v)throw new AssertionError(name);}
  static void near(float a,float b,float e,String n){ok(Math.abs(a-b)<e,n+" "+a+"/"+b);}
  static Developer.Source source(boolean flat){return new Developer.Source(){public int width(){return 67;}public int height(){return 49;}public void rgb(int x,int y,float[] out){if(x<0||y<0||x>=67||y>=49)throw new AssertionError("source bounds");float a=flat?.2f:x<33?.1f:.8f;out[0]=a;out[1]=a*.8f;out[2]=a*.7f;}};}
  static void crop(String directory)throws Exception{File dir=new File(directory);dir.mkdirs();File f=RawCalibrationTests.fixture(dir,false);RawFrame original=DngReader.read(f);short[] samples=original.pixels.clone();float[] before=new float[3];original.rgb(4,4,before);DngCrop.apply(f);RawFrame after=DngReader.read(f);ok(Arrays.equals(samples,after.pixels),"DNG sensor sample bytes unchanged");float[] rgb=new float[3];after.rgb(4,4,rgb);for(int c=0;c<3;c++)near(before[c],rgb[c],1e-6f,"DNG calibration unchanged");ByteBuffer b=ByteBuffer.wrap(Files.readAllBytes(f.toPath())).order(ByteOrder.LITTLE_ENDIAN);int root=b.getInt(4),count=b.getShort(root)&65535;int[] crop=null;for(int i=0;i<count;i++){int e=root+2+12*i;if((b.getShort(e)&65535)==50720){int pos=b.getInt(e+8);crop=new int[]{b.getInt(pos),b.getInt(pos+4)};}}ok(crop!=null&&crop[0]*2==crop[1]*3,"DNG default crop is 3:2");ok(after.width==original.width&&after.height==original.height,"DNG retains full sensor dimensions");long previous=f.length();DngCrop.apply(f);ok(f.length()>previous,"Metadata update remains valid on an already-cropped DNG");ok(Arrays.equals(samples,DngReader.read(f).pixels),"Repeated crop preserves samples");}
  static void endian(boolean little,boolean sub)throws Exception {ByteOrder order=little?ByteOrder.LITTLE_ENDIAN:ByteOrder.BIG_ENDIAN;ByteBuffer b=ByteBuffer.allocate(2048).order(order);b.put((byte)(little?'I':'M')).put((byte)(little?'I':'M')).putShort((short)42).putInt(8);int raw=sub?64:8;
    if(sub){b.position(8);b.putShort((short)1).putShort((short)330).putShort((short)4).putInt(1).putInt(raw).putInt(0);}
    b.position(raw);b.putShort((short)6);int[] tags={256,257,262,273,279,50829};int[] values={120,80,32803,600,128,500};for(int i=0;i<tags.length;i++)b.putShort((short)tags[i]).putShort((short)4).putInt(tags[i]==50829?4:1).putInt(values[i]);b.putInt(0);b.position(500);b.putInt(0).putInt(0).putInt(80).putInt(120);byte[] pixels=new byte[128];new Random(7).nextBytes(pixels);b.position(600);b.put(pixels);File f=File.createTempFile("press-dng-", ".dng");try{Files.write(f.toPath(),b.array());DngCrop.apply(f);byte[] result=Files.readAllBytes(f.toPath());ok(Arrays.equals(pixels,Arrays.copyOfRange(result,600,728)),"Raw strip unchanged, endian="+little+" sub="+sub);ByteBuffer out=ByteBuffer.wrap(result).order(order);int first=out.getInt(4),target=sub?out.getInt(first+10):first;int n=out.getShort(target)&65535;boolean got=false;for(int i=0;i<n;i++){int entry=target+2+i*12;if((out.getShort(entry)&65535)==50720){int offset=out.getInt(entry+8);ok(out.getInt(offset)*2==out.getInt(offset+4)*3,"Cross-endian crop ratio");got=true;}}ok(got,"Crop entry present");}finally{f.delete();}}
  public static void main(String[] args)throws Exception{for(int width:new int[]{64,4000,4032})for(int height:new int[]{48,3000})for(int rotation:new int[]{0,90,180,270}){Geometry g=new Geometry(width,height,rotation,1.5);ok(Math.max(g.width,g.height)*2==Math.min(g.width,g.height)*3,"Exact 3:2 output");for(int[] xy:new int[][]{{0,0},{g.width-1,g.height-1}})ok(g.sourceX(xy[0],xy[1])>=0&&g.sourceX(xy[0],xy[1])<width&&g.sourceY(xy[0],xy[1])>=0&&g.sourceY(xy[0],xy[1])<height,"Crop maps inside sensor");}
    for(int rotation:new int[]{0,90,180,270}){Developer.Source input=source(false);LandscapeSource output=new LandscapeSource(input,rotation);ok(output.width()>output.height()&&output.width()*2==output.height()*3,"Every rotation produces landscape 3:2");for(int[] point:new int[][]{{0,0},{output.width()-1,output.height()-1}}){float[] rgb=new float[3];output.rgb(point[0],point[1],rgb);ok(Float.isFinite(rgb[0]),"Landscape source reads in bounds");}File dir=new File(args[0]);dir.mkdirs();File raw=RawCalibrationTests.fixture(dir,false);short[] pixels=DngReader.read(raw).pixels.clone();DngCrop.applyLandscape(raw,rotation);ByteBuffer data=ByteBuffer.wrap(Files.readAllBytes(raw.toPath())).order(ByteOrder.LITTLE_ENDIAN);int off=data.getInt(4),entries=data.getShort(off)&65535;for(int k=0;k<entries;k++){int entry=off+2+12*k;if((data.getShort(entry)&65535)==50720){int pos=data.getInt(entry+8),cw=data.getInt(pos),ch=data.getInt(pos+4);if(rotation%180!=0){int swap=cw;cw=ch;ch=swap;}ok(cw>ch&&cw*2==ch*3,"DNG crop is landscape after orientation");}}ok(Arrays.equals(pixels,DngReader.read(raw).pixels),"Landscape DNG preserves pixels");}
    ok(ClippingRisk.high(250,0,0)&&!ClippingRisk.high(249,249,249),"Highlight channel boundary");ok(ClippingRisk.low(5,5,5)&&!ClippingRisk.low(0,0,6),"Shadow boundary");ClippingRisk.Tracker tracker=new ClippingRisk.Tracker();tracker.update(30,0,1024);ok(tracker.highlights&&!tracker.shadows,"Highlight warning");tracker.update(0,30,1024);ok(tracker.highlights&&tracker.shadows,"Both warnings during hold");tracker.update(0,30,1024);ok(!tracker.highlights&&tracker.shadows,"Clear stale highlight warning");ok(GuideAppearance.opacity(-1)==0&&GuideAppearance.opacity(101)==100,"Full opacity endpoints");for(int color:GuideAppearance.COLORS)ok(GuideAppearance.color(color)==color,"Palette supported");
    Recipe recipe=new Recipe();recipe.detail=.16f;Developer.Source flat=DetailEnhancement.wrap(source(true),recipe);float[] actual=new float[3];flat.rgb(32,24,actual);near(actual[0],.2f,1e-6f,"Uniform detail unchanged");Developer.Source edge=DetailEnhancement.wrap(source(false),recipe);float[] baseline=new float[3];for(int x=0;x<67;x++)for(int y=0;y<49;y++){edge.rgb(x,y,actual);source(false).rgb(x,y,baseline);for(int c=0;c<3;c++){ok(Float.isFinite(actual[c]),"Finite enhanced color");ok(Math.abs(actual[c]-baseline[c])<=.01201,"Bounded detail, column traversal");}}
    Recipe zero=new Recipe();ok(DetailEnhancement.wrap(source(true),zero).getClass()!=edge.getClass(),"Zero detail bypass");crop(args[0]);for(boolean le:new boolean[]{true,false})for(boolean sub:new boolean[]{true,false})endian(le,sub);System.out.println("PASS: "+checks+" press ratio/detail/DNG integrity assertions");}
}
